package com.gk.jobhelper.controller;
import com.gk.jobhelper.common.ApiResponse;import com.gk.jobhelper.dto.*;import com.gk.jobhelper.service.*;import org.springframework.web.bind.annotation.*;import javax.validation.Valid;
@RestController @RequestMapping("/api/recruitment") public class RecruitmentController {private final RecruitmentDiscoveryService discovery;private final RecruitmentNoticeService notices;public RecruitmentController(RecruitmentDiscoveryService d,RecruitmentNoticeService n){discovery=d;notices=n;}@PostMapping("/discovery")public ApiResponse<RecruitmentDiscoveryResult> discovery(){return ApiResponse.ok(discovery.discoverAll());}@GetMapping("/notices")public ApiResponse<PageVO<RecruitmentNoticeVO>> page(@RequestParam(required=false)String status,@RequestParam(required=false)String sourceCode,@RequestParam(required=false)String keyword,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){return ApiResponse.ok(notices.page(status,sourceCode,keyword,page,pageSize));}@GetMapping("/notices/{id}")public ApiResponse<RecruitmentNoticeVO> detail(@PathVariable Long id){return ApiResponse.ok(notices.detail(id));}@PutMapping("/notices/{id}/status")public ApiResponse<Void> status(@PathVariable Long id,@Valid @RequestBody RecruitmentNoticeStatusRequest request){notices.updateStatus(id,request.getStatus());return ApiResponse.ok();}@PostMapping("/notices/{id}/view")public ApiResponse<Void> view(@PathVariable Long id){notices.view(id);return ApiResponse.ok();}}
